CREATE TABLE `student_global_profile`
(
    `id`                       bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '全局画像主键ID',
    `user_id`                  bigint unsigned NOT NULL COMMENT '学生用户ID ',
    `profile_version`          int unsigned NOT NULL DEFAULT '1' COMMENT '全局画像版本号；  总体目标、能力、偏好或跨科目状态发生重要变化时递增，用于乐观锁、更新审计和历史追踪',
    `learning_background`      json                   DEFAULT NULL COMMENT '全局学习背景：学历阶段、年级、专业、通用技术基础、已修课程摘要和学习环境约束',
    `learning_goals`           json                   DEFAULT NULL COMMENT '全局学习目标：总体目标、跨科目目标、目标优先级、截止时间、时间预算和目标状态',
    `subject_mastery_overview` json                   DEFAULT NULL COMMENT '科目掌握总览：汇总各科目掌握水平、学习阶段、主要薄弱项、遗忘风险、最近学习时间及当前优先级；详细事实来源于单科画像',
    `ability_profile`          json                   DEFAULT NULL COMMENT '跨科目综合能力：概念理解、问题拆解、算法设计、代码实现、调试分析、知识迁移和表达能力',
    `misconception_profile`    json                   DEFAULT NULL COMMENT '跨科目易错模式：重复错误类型、可能原因、涉及科目、严重程度、证据ID、置信度和干预策略；具体错误保留在单科画像中',
    `learning_preference`      json                   DEFAULT NULL COMMENT '全局学习偏好：记录跨科目相对稳定且实际有效的资源形式、讲解顺序、内容粒度、练习方式、反馈方式及交互偏好',
    `metacognitive_profile`    json                   DEFAULT NULL COMMENT '元认知与自主学习能力：记录学习规划、过程监控、自我评估、学习反思、主动求助及信心校准能力，用于调整学习节奏和督学策略',
    `dimension_metadata`       json                   DEFAULT NULL COMMENT '画像维度元数据：各维度置信度、数据来源、证据数量、更新时间、有效期限及参与聚合的单科画像版本',
    `active_subject_ids`       json                   DEFAULT NULL COMMENT '当前正在学习的科目ID列表',
    `profile_summary`          text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '根据结构化画像生成的自然语言摘要；仅作为大模型上下文缓存，不作为画像事实源',
    `profile_completeness`     decimal(5, 2)          DEFAULT NULL COMMENT '全局画像完整度，0到100；表示支撑跨科目规划、资源推荐和总体评估所需关键信息的覆盖程度',
    `profile_confidence_score` decimal(5, 2) NOT NULL DEFAULT '0.00' COMMENT '全局画像整体可信度，0到100；根据基础资料、对话信息、学习行为及单科画像的一致性和时效性综合计算',
    `last_aggregated_at`       datetime               DEFAULT CURRENT_TIMESTAMP COMMENT '最近一次根据学生基础资料、对话信息及各单科画像重新聚合全局画像的时间',
    `created_at`               datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '全局画像创建时间',
    `updated_at`               datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '全局画像最近更新时间',
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_global_profile_user` (`user_id`,`profile_version`) USING BTREE,
    KEY                        `idx_global_profile_status_updated` (`updated_at`),
    KEY                        `idx_global_profile_aggregated_at` (`last_aggregated_at`),
    CONSTRAINT `chk_global_profile_version` CHECK ((`profile_version` >= 1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='学生全局动态画像表；每个用户保留一条当前画像，聚合跨科目稳定特征和总体学习状态，用于全局学习规划、资源推荐和学习效果评估';

CREATE TABLE `student_subject_profile`
(
    `id`                       bigint        NOT NULL AUTO_INCREMENT COMMENT '单科画像主键ID',
    `user_id`                  bigint        NOT NULL COMMENT '学生用户ID ',
    `subject_id`               bigint        NOT NULL COMMENT '学科ID ',
    `profile_version`          int           NOT NULL                                        DEFAULT '1' COMMENT '单科画像版本号；关键画像内容变化时递增，用于乐观锁、更新审计和历史追踪',
    `learning_goals`           json                                                          DEFAULT NULL COMMENT '学习目标画像：目标类型、目标能力、截止日期、优先级、时间预算和目标状态',
    `knowledge_mastery`        json                                                          DEFAULT NULL COMMENT '知识掌握画像：知识点掌握度、掌握状态、判断置信度、独立程度和遗忘风险',
    `misconception_profile`    json                                                          DEFAULT NULL COMMENT '易错模式画像：重复错误类型、可能原因、严重程度、证据、置信度和干预策略',
    `learning_preference`      json                                                          DEFAULT NULL COMMENT '学习偏好画像：资源形式、讲解顺序、内容粒度、练习方式、反馈方式和交互方式',
    `learning_behavior`        json                                                          DEFAULT NULL COMMENT '学习行为画像：指定统计周期内的学习频率、学习时长、资源完成率、提示使用率、复习率和主动提问率',
    `current_learning_state`   json                                                          DEFAULT NULL COMMENT '当前学习状态：当前目标、计划节点、知识点、任务、短期困难、参与状态和下一步行动',
    `dimension_metadata`       json                                                          DEFAULT NULL COMMENT '各画像维度的置信度、数据来源、更新时间、有效期限和证据数量',
    `profile_summary`          text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '画像自然语言摘要,根据结构化画像生成的自然语言摘要，属于可重新生成的缓存内容',
    `profile_completeness`     decimal(5, 2)                                                 DEFAULT NULL COMMENT '单科画像完整度，0到100 ',
    `profile_confidence_score` decimal(5, 2) NOT NULL                                        DEFAULT '0.00' COMMENT '单科画像整体可信度，0到100；根据数据来源、样本数量、数据时效及多源一致性综合计算',
    `last_update_reason`       varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '最近一次单科画像变化原因，如对话抽取、练习评估、学习行为变化或用户主动修改',
    `created_at`               datetime      NOT NULL                                        DEFAULT CURRENT_TIMESTAMP COMMENT '单科画像创建时间',
    `updated_at`               datetime      NOT NULL                                        DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '单科画像最近更新时间',
    `last_assessed_at`         datetime                                                      DEFAULT CURRENT_TIMESTAMP COMMENT '最近一次基于对话、练习和学习行为数据重新评估单科画像的时间',
    `next_refresh_at`          datetime                                                      DEFAULT NULL COMMENT '计划下次主动评估单科画像的时间；为空时由对话、练习或学习行为事件触发更新',
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_subject_profile_user_subject` (`user_id`,`subject_id`,`profile_version`) USING BTREE,
    KEY                        `idx_user_id` (`user_id`),
    KEY                        `idx_subject` (`subject_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='学生单科动态画像表；每个用户在每个科目保留一条当前画像，用于个性化资源生成、学习路径规划、精准推送和学习效果评估';